from __future__ import annotations
import cmath, math, itertools

def sigma5(n: int, tol: float = 1e-9) -> float:
    roots: list[complex] = [cmath.exp(2j * math.pi * k / 5.0) for k in range(5)]
    best: float = math.inf
    for combo in itertools.combinations_with_replacement(range(5), n):
        s: complex = 0j
        for k in combo:
            s += roots[k]
        m: float = abs(s)
        if m > tol:
            best = min(best, m)
    return best

from __future__ import annotations

def period_powersum(n: int) -> int:
    a, b = 2, 1  # L0, L1
    for _ in range(n):
        a, b = b, a + b
    return ((-1) ** n) * a

def period_diffsq(n: int) -> int:
    a, b = 0, 1  # F0, F1
    for _ in range(n):
        a, b = b, a + b
    return 5 * a * a

